mapper.select:
SELECT usr_id
FROM diet_mgmt
WHERE diet_id = #{dietId}

SELECT usr_id
FROM usr_tray_mgmt
WHERE tray_id = #{trayId}

    	SELECT a.diet_id, a.diet_nm, a.diet_desc, a.diet_fav_flg, a.tray_id, a.tray_nm,
		   a.std_cd, a.std_nm, TO_CHAR(COALESCE(a.upd_dt, a.cre_dt), 'YYYY-MM-DD"T"HH24:MI:SS') AS upd_dt
    	FROM diet_mgmt a
    	WHERE a.usr_id = #{usrId}

    	AND a.diet_nm = #{dietNm}


    	AND a.tray_id = #{trayId}


    	AND a.diet_id = #{dietId}

    	ORDER BY a.upd_dt DESC, a.diet_id

SELECT sub1.tmpl_std_cd, sub1.tmpl_std_nm, sub1.tmpl_std_tp_cd, a.intg_cd_dp_val_desc AS tmpl_std_tp_nm, json_agg( json_build_object( 'code', sub1.tmpl_nutr_cd, 'name', b.nutr_nm, 'unitCode', b.unit_cd, 'unitName', c.intg_cd_dp_val_desc, 'mandatoryFlag', sub1.tmpl_nutr_mand_flg, 'weightFrom', sub1.tmpl_nutr_wgt_fm, 'weightTo', sub1.tmpl_nutr_wgt_to, 'formula', sub1.tmpl_nutr_foml )) AS nutrients FROM ( SELECT std.tmpl_std_cd, std.tmpl_std_nm, std.tmpl_std_tp_cd, dtl.tmpl_nutr_cd, dtl.tmpl_nutr_mand_flg, dtl.tmpl_nutr_wgt_fm, dtl.tmpl_nutr_wgt_to, dtl.tmpl_nutr_foml, std.dp_seq FROM tmpl_diet_std std INNER JOIN tmpl_diet_std_dtl dtl ON std.tmpl_std_cd = dtl.tmpl_std_cd WHERE std.tmpl_std_cd != 'USR' UNION ALL SELECT std.std_cd, std.std_nm, NULL, dtl.nutr_cd, dtl.nutr_mand_flg, dtl.nutr_wgt_fm, dtl.nutr_wgt_to, dtl.nutr_foml, 99 AS dp_seq FROM diet_mgmt std INNER JOIN diet_std_dtl_mgmt dtl ON std.diet_id = dtl.diet_id WHERE 1 = 1 AND std.std_cd = #{usrStdCd}
AND std.diet_id = #{dietId}
AND 1 = 2
) sub1 LEFT OUTER JOIN com_intg_cd_dtl a ON ( a.intg_cd = 'CD00014' AND a.intg_cd_val_ctnt = sub1.tmpl_std_tp_cd ) LEFT OUTER JOIN mst_nutr b ON sub1.tmpl_nutr_cd = b.nutr_cd LEFT OUTER JOIN com_intg_cd_dtl c ON ( c.intg_cd = 'CD00012' AND c.intg_cd_val_ctnt = b.unit_cd ) GROUP BY sub1.tmpl_std_cd, sub1.tmpl_std_nm, sub1.tmpl_std_tp_cd, sub1.dp_seq, a.intg_cd_dp_val_desc ORDER BY sub1.dp_seq

SELECT DISTINCT a.fd_tp_cd FROM (
SELECT #{item} AS fd_tp_cd
) a WHERE NOT EXISTS ( SELECT 1 FROM com_intg_cd_dtl WHERE intg_cd = 'CD00013' AND intg_cd_val_ctnt = a.fd_tp_cd )

SELECT DISTINCT a.fd_cd FROM (
SELECT #{item} AS fd_cd
) a WHERE NOT EXISTS ( SELECT 1 FROM mst_fd WHERE fd_cd = a.fd_cd )

SELECT DISTINCT a.mat_cd FROM (
SELECT #{item} AS mat_cd
) a WHERE NOT EXISTS ( SELECT 1 FROM mst_mat WHERE mat_cd = a.mat_cd )

SELECT DISTINCT a.nutr_cd FROM (
SELECT #{item} AS nutr_cd
) a WHERE NOT EXISTS ( SELECT 1 FROM mst_nutr WHERE nutr_cd = a.nutr_cd )

SELECT DISTINCT a.id FROM (
SELECT #{item} AS id
) a WHERE NOT EXISTS ( SELECT 1 FROM mst_alrg WHERE alrg_id = a.id )

update.foreach:
   		UPDATE diet_fd_dtl_mgmt


            mat_rcp_wgt = #{item.matRcpWgt}::numeric,


            mat_calc_wgt = #{item.matCalcWgt}::numeric,


            mat_prc = #{item.matPrc},


            rct_incl_flg = #{item.rctInclFlg},


            upd_usr_id = #{item.updUsrId},


            upd_dt = #{item.updDt},


	        WHERE diet_id = #{item.dietId}
	        AND fd_seq = #{item.fdSeq}
	        AND mat_cd = #{item.matCd}

mapper.select:
SELECT rct_id, diet_id, unit_prc, serv_qty, adj_pct, fnl_prc, cre_usr_id, cre_dt, upd_usr_id, upd_dt
FROM diet_rct
WHERE diet_id = #{dietId}

SELECT recdtl.rec_seq AS fd_seq, recdtl.fd_cd, COALESCE( (SELECT fd_nm FROM usr_fd_mgmt WHERE usr_id = #{usrId} AND fd_cd = recdtl.fd_cd), fd.fd_nm ) AS fd_nm, COALESCE( (SELECT fd_rcp_desc FROM usr_fd_mgmt WHERE usr_id = #{usrId} AND fd_cd = recdtl.fd_cd), fd.fd_rcp_desc ) AS fd_rcp_desc, fd.fd_tp_cd FROM tmpl_tray tray INNER JOIN tmpl_fd_rec rec ON tray.tmpl_tray_cd = rec.tmpl_tray_cd INNER JOIN tmpl_fd_rec_dtl recdtl ON rec.rec_id = recdtl.rec_id INNER JOIN mst_fd fd ON recdtl.fd_cd = fd.fd_cd WHERE 1 = 1
AND tray.tmpl_tray_nm = #{trayNm}
AND 1 = 2
AND rec.tmpl_std_cd = #{stdCd}
AND 1 = 2
AND ( (rec.fm_mon <= rec.to_mon AND #{month} BETWEEN rec.fm_mon AND rec.to_mon) OR (rec.fm_mon = 12 AND (#{month} = 12 OR #{month} <= rec.to_mon)) ) ORDER BY recdtl.rec_seq

select.if:
SELECT mst.fd_cd, COALESCE( (SELECT fd_nm FROM usr_fd_mgmt WHERE usr_id = #{usrId} AND fd_cd = mst.fd_cd), mst.fd_nm ) AS fd_nm, COALESCE( (SELECT fd_rcp_desc FROM usr_fd_mgmt WHERE usr_id = #{usrId} AND fd_cd = mst.fd_cd), mst.fd_rcp_desc ) AS fd_rcp_desc, mst.fd_tp_cd FROM ( SELECT UNNEST(ARRAY[ fd_${item.alias} ]) AS fd_cd FROM ( SELECT * FROM ( SELECT
${item.alias}.fd_cd AS fd_${item.alias} ,
${item.alias}.ENG AS ttl_eng,
${item.alias}.NA AS ttl_na,
${item.alias}.PROTEIN AS ttl_protein,
${item.alias}.SUGAR AS ttl_sugar,
${item.alias}.SFA AS ttl_sfa FROM
( SELECT * FROM mst_fd_nutr WHERE 1 = 1 AND fd_tp_cd = #{item.typeCode} AND fd_cd NOT IN (SELECT fd_cd FROM mst_fd WHERE own_usr_id IS NOT NULL) AND ENG <= 800.0 * ${ratio} AND NA <= 1350.0 * ${ratio}
AND ( alrg_ids IS NULL OR NOT ( alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
) ${item.alias}
) tmp1 WHERE 1 = 1 AND ttl_eng >= 500.0 * ${ratio} AND ttl_eng <= 800.0 * ${ratio} AND ttl_na <= 1350.0 * ${ratio} AND ttl_protein >= 18.0 * ${ratio} AND ttl_sugar < ttl_eng * 0.1 / 4 AND ttl_sfa < ttl_eng * 0.1 / 9
AND EXISTS ( SELECT 1 FROM mst_fd_nutr WHERE 1 = 1 AND fd_tp_cd = #{item.typeCode} AND fd_cd NOT IN (SELECT fd_cd FROM mst_fd WHERE own_usr_id IS NOT NULL) AND ENG <= 800.0 * ${ratio} AND NA <= 1350.0 * ${ratio}
AND ( alrg_ids IS NULL OR NOT ( alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
)
LIMIT 1 ) tmp2 ) tmp3 INNER JOIN mst_fd mst ON tmp3.fd_cd = mst.fd_cd

		SELECT
		    mst.fd_cd,
			COALESCE(
				(SELECT fd_nm
				FROM usr_fd_mgmt
				WHERE usr_id = #{usrId}
				AND fd_cd = mst.fd_cd),
				mst.fd_nm
			) AS fd_nm,
		    COALESCE(
    			(SELECT fd_rcp_desc
    			FROM usr_fd_mgmt
    			WHERE usr_id = #{usrId}
    			AND fd_cd = mst.fd_cd),
    			mst.fd_rcp_desc
    		) AS fd_rcp_desc,
		    mst.fd_tp_cd
		FROM
		    (
		        SELECT
		            UNNEST(ARRAY[
		            fd_${item.alias}
		        ]) AS fd_cd
		        FROM
		            (
		                SELECT
		                    *
		                FROM
		                    (
		                        SELECT

		                            ${item.alias}.fd_cd AS fd_${item.alias}
		                            ,

		                            ${item.alias}.ENG
		                             AS ttl_eng,

		                            ${item.alias}.NA
		                             AS ttl_na,

		                            ${item.alias}.PROTEIN
		                             AS ttl_protein
		                        FROM

		                            (
		                                SELECT
		                                    *
		                                FROM
		                                    mst_fd_nutr
		                                WHERE
		                                    1 = 1
		                                    AND fd_tp_cd = #{item.typeCode}
		                                    AND fd_cd NOT IN (SELECT fd_cd FROM mst_fd WHERE own_usr_id IS NOT NULL)
		                                    AND ENG <= 800.0 * ${ratio}
		                                    AND NA <= 650.0 * ${ratio}

											AND (
												alrg_ids IS NULL 
												OR NOT (
													alrg_ids && #{excludedAllergenIds, 
																	jdbcType=ARRAY, 
																	javaType=java.util.List, 
																	typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler}
												)
											)

		                            ) ${item.alias}

		                    ) tmp1
		                WHERE
		                    1 = 1
		                    AND ttl_eng >= 500.0 * ${ratio}
		                    AND ttl_eng <= 800.0 * ${ratio}
		                    AND ttl_na <= 650.0 * ${ratio}
		                    AND ttl_protein >= ttl_eng * 0.12 / 4

		                    AND EXISTS (
		                            SELECT
		                                1
		                            FROM
		                                mst_fd_nutr
		                            WHERE
		                                1 = 1
		                                AND fd_tp_cd = #{item.typeCode}
		                                AND fd_cd NOT IN (SELECT fd_cd FROM mst_fd WHERE own_usr_id IS NOT NULL)
		                                AND ENG <= 800.0 * ${ratio}
		                                AND NA <= 650.0 * ${ratio}

										AND (
											alrg_ids IS NULL 
											OR NOT (
												alrg_ids && #{excludedAllergenIds, 
																jdbcType=ARRAY, 
																javaType=java.util.List, 
																typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler}
											)
										)

		                        )

		                LIMIT
		                    1
		            ) tmp2
		    ) tmp3
		    INNER JOIN mst_fd mst ON tmp3.fd_cd = mst.fd_cd

