) tmp1 WHERE 1 = 1 AND ttl_eng >= 500.0 * ${ratio} AND ttl_eng <= 600.0 * ${ratio} AND ttl_na <= 1000.0 * ${ratio} AND ttl_sugar < ttl_eng * 0.1 / 4 AND ttl_protein >= 18.0 * ${ratio} AND ttl_fat >= ttl_eng * 0.15 / 9 AND ttl_fat <= ttl_eng * 0.30 / 9 AND ttl_sfa < ttl_eng * 0.1 / 9
AND EXISTS ( SELECT 1 FROM mst_fd_nutr WHERE 1 = 1 AND fd_tp_cd = #{item.typeCode} AND fd_cd NOT IN (SELECT fd_cd FROM mst_fd WHERE own_usr_id IS NOT NULL) AND ENG <= 600.0 * ${ratio} AND NA <= 1000.0 * ${ratio}
AND ( alrg_ids IS NULL OR NOT ( alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
)
LIMIT 1 ) tmp2 ) tmp3 INNER JOIN mst_fd mst ON tmp3.fd_cd = mst.fd_cd

mapper.select:
SELECT mst.tray_id, mst.usr_id, mst.tray_nm, mst.rep_tray_cd, rtray.intg_cd_dp_val_desc AS rep_tray_nm, rtray.intg_cd_val_desc AS rep_tray_desc, COALESCE(mst.tray_mand_flg, 'N') AS tray_mand_flg, COALESCE( jsonb_agg( json_build_object( 'sequence', dtl.fd_seq, 'mandatoryFlag', dtl.fd_mand_flg, 'separatedFlag', dtl.fd_sep_flg, 'capacityVolume', dtl.fd_capa_vol, 'typeCode', dtl.fd_tp_cd, 'typeName', fdtp.intg_cd_dp_val_desc, 'unitCode', dtl.unit_cd, 'unitName', d.intg_cd_dp_val_desc ) ORDER BY dtl.fd_seq ) FILTER (WHERE dtl.fd_seq IS NOT NULL), '[]'::jsonb) AS foods FROM usr_tray_mgmt mst LEFT OUTER JOIN usr_tray_dtl_mgmt dtl ON mst.tray_id = dtl.tray_id LEFT OUTER JOIN com_intg_cd_dtl d ON ( d.intg_cd = 'CD00012' AND d.intg_cd_val_ctnt = dtl.unit_cd ) LEFT OUTER JOIN com_intg_cd_dtl fdtp ON ( fdtp.intg_cd = 'CD00013' AND fdtp.intg_cd_val_ctnt = dtl.fd_tp_cd ) LEFT OUTER JOIN com_intg_cd_dtl rtray ON ( rtray.intg_cd = 'CD00015' AND rtray.intg_cd_val_ctnt = mst.rep_tray_cd ) WHERE mst.usr_id = #{usrId}
AND mst.diet_id = #{dietId}
GROUP BY mst.tray_id, mst.usr_id, mst.tray_nm, mst.rep_tray_cd, rtray.intg_cd_dp_val_desc, rtray.intg_cd_val_desc, COALESCE(mst.tray_mand_flg, 'N')

SELECT tray_id, usr_id, tray_nm, rep_tray_cd, tray_mand_flg
FROM usr_tray_mgmt
WHERE usr_id = #{usrId}
AND tray_nm = #{trayNm}

SELECT * FROM ( SELECT * FROM ( SELECT usr.fd_cd, usr.fd_nm, fd.fd_tp_cd, 1 AS tp FROM usr_fd_mgmt usr INNER JOIN mst_fd_nutr fdnutr ON usr.fd_cd = fdnutr.fd_cd INNER JOIN mst_fd fd ON usr.fd_cd = fd.fd_cd WHERE 1 = 1 AND usr.usr_id = #{usrId}
AND ( fdnutr.alrg_ids IS NULL OR NOT ( fdnutr.alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
AND UPPER(usr.fd_nm) LIKE '%' || UPPER(#{keyword}) || '%'
) grp1 UNION ALL SELECT * FROM ( SELECT fd.fd_cd, fd.fd_nm, fd.fd_tp_cd, 2 AS tp FROM mst_fd fd INNER JOIN mst_fd_nutr fdnutr ON fd.fd_cd = fdnutr.fd_cd WHERE 1 = 1 AND fd.own_usr_id IS NULL
AND ( fdnutr.alrg_ids IS NULL OR NOT ( fdnutr.alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
AND UPPER(fd.fd_nm) LIKE '%' || UPPER(#{keyword}) || '%'
) grp2 ) sub WHERE 1 = 1
CASE WHEN fd_tp_cd = #{fdTpCd} THEN 0 ELSE 1 END,
POSITION(UPPER(#{keyword}) IN UPPER(fd_nm)), LENGTH(fd_nm)
LIMIT ${limit}

SELECT fd_cd, fd_nm, fd_tp_cd, fd_tp_nm, fd_rcp_desc, total_record_no FROM ( SELECT fd.fd_cd, fd.fd_nm, fd.fd_tp_cd, fdtp.intg_cd_dp_val_desc AS fd_tp_nm, fd.fd_rcp_desc, count(*) OVER() AS total_record_no FROM mst_fd fd INNER JOIN mst_fd_nutr fdnutr ON fd.fd_cd = fdnutr.fd_cd LEFT OUTER JOIN com_intg_cd_dtl fdtp ON ( fdtp.intg_cd = 'CD00013' AND fdtp.intg_cd_val_ctnt = fd.fd_tp_cd ) WHERE 1 = 1 AND fd.own_usr_id IS NULL
AND fd.fd_tp_cd = #{fdTpCd}
AND ( fdnutr.alrg_ids IS NULL OR NOT ( fdnutr.alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
AND UPPER(fd.fd_nm) LIKE #{keyword}
AND EXISTS ( SELECT 1 FROM tmpl_fd tf WHERE tf.tmpl_fd_cd = fd.fd_cd AND tf.tmpl_mat_cd = #{matCd} )
) sub ORDER BY fd_nm COLLATE "ko-KR-x-icu"
OFFSET #{offset}
LIMIT #{limit}

SELECT fd_cd, fd_nm, fd_tp_cd, fd_tp_nm, fd_rcp_desc, own_flg, total_record_no FROM ( SELECT usr.fd_cd, usr.fd_nm, fd.fd_tp_cd, fdtp.intg_cd_dp_val_desc AS fd_tp_nm, usr.fd_rcp_desc, usr.upd_dt, usr.cre_dt, CASE WHEN fd.own_usr_id IS NULL THEN 'N' ELSE 'Y' END AS own_flg, count(*) OVER() AS total_record_no FROM usr_fd_mgmt usr INNER JOIN mst_fd fd ON usr.fd_cd = fd.fd_cd LEFT OUTER JOIN com_intg_cd_dtl fdtp ON ( fdtp.intg_cd = 'CD00013' AND fdtp.intg_cd_val_ctnt = fd.fd_tp_cd ) WHERE usr.usr_id = #{usrId}
AND fd.fd_tp_cd = #{fdTpCd}
AND UPPER(usr.fd_nm) LIKE #{keyword}
AND EXISTS ( SELECT 1 FROM tmpl_fd tf WHERE tf.tmpl_fd_cd = usr.fd_cd AND tf.tmpl_mat_cd = #{matCd} )
) sub ORDER BY COALESCE(upd_dt, cre_dt) DESC
OFFSET #{offset}
LIMIT #{limit}

SELECT
	rec.recommend_fd_cd AS fd_cd,
	fd.fd_nm
FROM fd_recommend rec
INNER JOIN mst_fd fd
	ON fd.fd_cd = rec.recommend_fd_cd
INNER JOIN mst_fd_nutr fdnutr
	ON fdnutr.fd_cd = rec.recommend_fd_cd
WHERE rec.fd_cd = #{fdCd}

	AND fd.fd_tp_cd = #{fdTpCd}


	AND (
		fdnutr.alrg_ids IS NULL
		OR NOT (
			fdnutr.alrg_ids && #{excludedAllergenIds,
							jdbcType=ARRAY,
							javaType=java.util.List,
							typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler}
		)
	)


	AND rec.recommend_fd_cd NOT IN

		#{fdCd}


ORDER BY rec.recommend_order ASC
LIMIT #{limit}

SELECT fd.fd_cd, fd.fd_nm FROM mst_fd fd INNER JOIN mst_fd_nutr fdnutr ON fdnutr.fd_cd = fd.fd_cd WHERE fd.fd_tp_cd = #{fdTpCd} AND fd.own_usr_id IS NULL
AND ( fdnutr.alrg_ids IS NULL OR NOT ( fdnutr.alrg_ids && #{excludedAllergenIds, jdbcType=ARRAY, javaType=java.util.List, typeHandler=egovframework.com.config.mybatis.JdbcArrayAndJavaListTypeHandler} ) )
AND fd.fd_cd NOT IN
#{fdCd}
ORDER BY RANDOM() LIMIT #{limit}

SELECT fd_tp_cd
FROM mst_fd
WHERE fd_cd = #{fdCd}

SELECT nutr_cd, nutr_wgt_fm, nutr_wgt_to, nutr_foml
FROM diet_std_dtl_mgmt
WHERE diet_id = #{dietId}

SELECT *
FROM usr_fd_mgmt
WHERE usr_id = #{usrId}
AND fd_cd = #{fdCd}

SELECT mat_cat_id, mat_cat_cd, mat_cat_nm, mat_tp_cd FROM tmpl_mat_cat WHERE 1 = 1
AND mat_tp_cd = #{typeCode}
ORDER BY mat_cat_nm COLLATE "ko-KR-x-icu"

SELECT mat_rep_id, mat_rep_nm, mat_cat_id FROM tmpl_mat_rep WHERE 1 = 1
AND mat_cat_id = #{categoryId}
ORDER BY mat_rep_nm COLLATE "ko-KR-x-icu"

SELECT mat_cd, mat_org_cd, mat_org_nm AS mat_nm, unit_cd, unit_nm, mat_cat_id, mat_cat_nm, type_nm, rep_nm, weight, CASE WHEN nutr_no != 0 THEN nutrients END AS nutrients, in_use, total_record_no FROM ( SELECT a.mat_cd, a.mat_org_cd, a.mat_org_nm, a.unit_cd, d.intg_cd_dp_val_desc AS unit_nm, matcat.mat_cat_id, matcat.mat_cat_nm, MAX(mattype.mat_tp_nm) AS type_nm, MAX(matrep.mat_rep_nm) AS rep_nm, MAX(b.tmpl_mat_wgt) AS weight, json_agg( json_build_object( 'code', c.nutr_cd, 'name', c.nutr_nm, 'amount', b.tmpl_nutr_amt / b.tmpl_mat_wgt, 'unitCode', c.unit_cd, 'unitName', e.intg_cd_dp_val_desc ) ) AS nutrients, count(CASE WHEN c.nutr_cd IS NOT NULL THEN 1 END) AS nutr_no, EXISTS ( SELECT 1 FROM diet_fd_dtl_mgmt WHERE mat_cd = a.mat_cd ) AS in_use, count(*) OVER() AS total_record_no FROM mst_mat a LEFT OUTER JOIN tmpl_mat_rep matrep ON a.mat_rep_id = matrep.mat_rep_id LEFT OUTER JOIN tmpl_mat_cat matcat ON matrep.mat_cat_id = matcat.mat_cat_id LEFT OUTER JOIN tmpl_mat_tp mattype ON matcat.mat_tp_cd = mattype.mat_tp_cd LEFT OUTER JOIN tmpl_mat b ON a.mat_cd = b.tmpl_mat_cd LEFT OUTER JOIN mst_nutr c ON b.tmpl_nutr_cd = c.nutr_cd LEFT OUTER JOIN com_intg_cd_dtl d ON ( d.intg_cd = 'CD00012' AND d.intg_cd_val_ctnt = a.unit_cd ) LEFT OUTER JOIN com_intg_cd_dtl e ON ( e.intg_cd = 'CD00012' AND e.intg_cd_val_ctnt = c.unit_cd ) WHERE a.cre_usr_id = #{creUsrId}
AND UPPER(a.mat_org_nm) LIKE #{keyword}
AND a.mat_cd = #{matCd}
GROUP BY a.mat_cd, a.mat_org_cd, a.mat_org_nm, a.unit_cd, d.intg_cd_dp_val_desc, matcat.mat_cat_id, matcat.mat_cat_nm ) sub ORDER BY mat_org_nm COLLATE "ko-KR-x-icu"
OFFSET #{offset}
LIMIT #{limit}

